// DiesisPatronBinding provides typed calls, transactions, logs, and offline ABI encoding.
type DiesisPatronBinding struct {
	abi     abi.ABI
	bound   *bind.BoundContract
	backend bind.ContractBackend
	address common.Address
}

// NewDiesisPatronBinding parses the ABI and binds an optional backend. Pass nil for offline encoding and decoding.
func NewDiesisPatronBinding(address common.Address, backend bind.ContractBackend) (*DiesisPatronBinding, error) {
	parsed, err := abi.JSON(strings.NewReader(DiesisPatronABI))
	if err != nil {
		return nil, err
	}
	var bound *bind.BoundContract
	if backend != nil {
		bound = bind.NewBoundContract(address, parsed, backend, backend, backend)
	}
	return &DiesisPatronBinding{abi: parsed, bound: bound, backend: backend, address: address}, nil
}

// ABI returns the parsed contract ABI.
func (c *DiesisPatronBinding) ABI() abi.ABI { return c.abi }

func (c *DiesisPatronBinding) method(signature string) (abi.Method, error) {
	for _, method := range c.abi.Methods {
		if method.Sig == signature {
			return method, nil
		}
	}
	return abi.Method{}, fmt.Errorf("unknown method %s", signature)
}

func (c *DiesisPatronBinding) event(signature string) (abi.Event, error) {
	for _, event := range c.abi.Events {
		if event.Sig == signature {
			return event, nil
		}
	}
	return abi.Event{}, fmt.Errorf("unknown event %s", signature)
}

func (c *DiesisPatronBinding) customError(signature string) (abi.Error, error) {
	for _, definition := range c.abi.Errors {
		if definition.Sig == signature {
			return definition, nil
		}
	}
	return abi.Error{}, fmt.Errorf("unknown error %s", signature)
}

// EncodeConstructor encodes the constructor arguments without bytecode.
func (c *DiesisPatronBinding) EncodeConstructor(params DiesisPatronConstructorParams) ([]byte, error) {
	return c.abi.Pack("", params.Owner, params.Staking)
}

// DeployDiesisPatronBinding deploys caller-supplied bytecode with typed constructor arguments.
func DeployDiesisPatronBinding(opts *bind.TransactOpts, backend bind.ContractBackend, bytecode []byte, params DiesisPatronConstructorParams) (common.Address, *types.Transaction, *DiesisPatronBinding, error) {
	if opts == nil || backend == nil {
		return common.Address{}, nil, nil, fmt.Errorf("transaction options and backend are required")
	}
	if len(bytecode) == 0 {
		return common.Address{}, nil, nil, fmt.Errorf("deployment bytecode is empty")
	}
	if opts.Value != nil && opts.Value.Sign() != 0 {
		return common.Address{}, nil, nil, fmt.Errorf("constructor is not payable")
	}
	parsed, err := abi.JSON(strings.NewReader(DiesisPatronABI))
	if err != nil {
		return common.Address{}, nil, nil, err
	}
	address, tx, _, err := bind.DeployContract(opts, parsed, bytecode, backend, params.Owner, params.Staking)
	if err != nil {
		return common.Address{}, nil, nil, err
	}
	binding, err := NewDiesisPatronBinding(address, backend)
	if err != nil {
		return common.Address{}, nil, nil, err
	}
	return address, tx, binding, nil
}

